#!/usr/bin/env node
// Disposable consolidation runner for the schema-14 verification-preparation package (round 3:
// after the second review, whose controller proof failed 9/11 on gitignored Cargo/Tauri build output,
// whose artifact check found stale manifest/checksum entries, and which flagged obsolete Cargo claims).
// Derived from consolidate-round2.mjs; the round-2 receipt it produced is embedded whole under
// reviewHistory.round2Receipt so no earlier evidence is lost.
// Lives outside the repository; its full source and SHA-256 are embedded in the receipt it writes.
// Runs every required command from the clone with Node 22 first on PATH, records argv, cwd,
// runtime, exit, full stdout/stderr and parsed counts, then writes one consolidated receipt.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';

const WT = process.cwd();
const SELF = new URL(import.meta.url).pathname;
const NODE22_BIN = '/opt/homebrew/opt/node@22/bin';
const OUT = path.join(WT, 'docs', 'evidence', 'mac-schema14-verification-preparation-2026-10-11', 'verification-receipts.json');
const env = { ...process.env, PATH: `${NODE22_BIN}:${process.env.PATH}` };
const sha = buf => crypto.createHash('sha256').update(buf).digest('hex');

function run(argv, { cwd = WT } = {}) {
  const startedAt = new Date().toISOString();
  const t0 = Date.now();
  const r = spawnSync(argv[0], argv.slice(1), { cwd, env, encoding: 'utf8', maxBuffer: 512 * 1024 * 1024 });
  return { argv, cwd, startedAt, durationMs: Date.now() - t0, exit: r.status, signal: r.signal, stdout: r.stdout, stderr: r.stderr };
}
const text = argv => run(argv).stdout.trim();

if (!text(['node', '--version']).startsWith('v22.')) { console.error('REFUSED: Node 22 is not first on PATH'); process.exit(2); }

const ALLOWED = [
  'scripts/mac-schema13-profile-snapshot.mjs', 'scripts/mac-schema14-profile-snapshot.mjs', 'scripts/mac-schema14-profile-snapshot.test.mjs',
  'scripts/mac-schema14-verification-proof.mjs', 'src/logic/currentSchemaVerification.test.ts',
  'docs/MAC_SCHEMA14_VERIFICATION_PREPARATION_REPORT_2026-10-11.md', 'docs/PROJECT_HANDOFF.md',
];

/* ---------------- identity, base hashes and ownership ---------------- */
const head = text(['git', 'rev-parse', 'HEAD']);
const porcelain = run(['git', 'status', '--porcelain=v1', '--untracked-files=all']).stdout.split('\n').filter(Boolean); // untrimmed: column 1 may be a space
const baseHashes = ALLOWED.map(p => {
  const atHead = spawnSync('git', ['show', `HEAD:${p}`], { cwd: WT, env, maxBuffer: 64 * 1024 * 1024 });
  return { path: p, atPinnedHead: atHead.status === 0 ? sha(atHead.stdout) : 'absent at pinned HEAD (new file)', current: sha(fs.readFileSync(path.join(WT, p))) };
});
const identity = {
  pinnedCommit: '8a260c0b32bc213850ed85bf9488d6ef571354a9',
  head,
  headMatchesPin: head === '8a260c0b32bc213850ed85bf9488d6ef571354a9',
  branch: text(['git', 'rev-parse', '--abbrev-ref', 'HEAD']),
  worktree: WT,
  isolatedClone: {
    path: path.resolve(WT, '..', 'isolated-repo'),
    head: text(['git', '-C', path.resolve(WT, '..', 'isolated-repo'), 'rev-parse', 'HEAD']),
    branches: text(['git', '-C', path.resolve(WT, '..', 'isolated-repo'), 'branch', '-a']).split('\n').map(s => s.trim()),
    remotes: text(['git', '-C', path.resolve(WT, '..', 'isolated-repo'), 'remote', '-v']) || '(none: remote removed after cloning)',
    creationLogs: {
      'clone.log': fs.readFileSync(path.resolve(WT, '..', 'clone.log'), 'utf8'),
      'worktree.log': fs.readFileSync(path.resolve(WT, '..', 'worktree.log'), 'utf8'),
    },
  },
  worktreeList: text(['git', 'worktree', 'list']),
  statusPorcelain: porcelain,
  trackedDiffStat: text(['git', 'diff', '--stat']),
  preEditBaseline: {
    limitation: 'NOT an observed pre-edit receipt. No receipt of the clone\'s clean state was saved before editing began, so the observed clean pre-edit state is not established by this package. What follows is a reconstruction: the hashes each allowed path had at the immutable pinned HEAD (git show HEAD:<path>), and the current proof that no tracked path outside the allowed list differs from HEAD.',
    method: 'git show HEAD:<path> for each allowed path; git status for paths outside the allowed list; independently, proof stage source-identity re-checks the tree without a git process.',
    allowedPathHashes: baseHashes,
    protectedTrackedChangesOutsideAllowedPaths: porcelain
      .map(l => l.slice(3)).filter(p => !ALLOWED.includes(p) && !p.startsWith('docs/evidence/mac-schema14-verification-preparation-2026-10-11/') && p !== 'node_modules'),
  },
};
const originalWorktrees = fs.readFileSync('/tmp/hfd-schema14-consolidate/original-worktrees.txt', 'utf8');
const refreshedWorktrees = fs.readFileSync('/tmp/hfd-schema14-consolidate/worktrees-round2.txt', 'utf8');
const round3Worktrees = fs.readFileSync('/private/tmp/hfd-schema14-consolidate/round3/worktrees-round3.txt', 'utf8');
const ownership = {
  command: 'git -C /Users/rickymac/code/Flight-training- worktree list (read-only; run inside the sandbox)',
  output: originalWorktrees,
  outputNote: 'first capture, taken during the earlier run of this assignment (not before the first edit; see preEditBaseline.limitation)',
  refreshedOutput: refreshedWorktrees,
  refreshedNote: 'second capture, taken in round 2 before regenerating these receipts; one Codex worktree moved to codex/queue-date-metadata-fixes-2026-10-12, which is not schema-14 helper work',
  round3Output: round3Worktrees,
  round3Note: 'third capture, taken in round 3 before regenerating these receipts; new since round 2: claude/m4-round4-review (M4 review, not schema-14 helper work)',
  competingSchema14Helper: /schema14|schema-14|current-schema/i.test(originalWorktrees + refreshedWorktrees + round3Worktrees) ? 'possible: inspect' : 'none: no worktree or branch names schema-14 helper work',
  committedSchema14HelperAtPin: spawnSync('git', ['cat-file', '-e', 'HEAD:scripts/mac-schema14-profile-snapshot.mjs'], { cwd: WT }).status === 0,
};

/* ---------------- required commands ---------------- */
const commands = [];
function record(label, argv, parse) {
  const r = run(argv);
  let counts = null;
  try { counts = parse ? parse(r) : null; } catch (error) { counts = { parseError: String(error.message) }; }
  commands.push({ label, ...r, counts });
  console.log(`${label}: exit ${r.exit} (${r.durationMs} ms)`);
  return r;
}
const vitestCounts = r => {
  const files = r.stdout.match(/Test Files\s+(\d+) passed \((\d+)\)/);
  const tests = r.stdout.match(/Tests\s+(\d+) passed \((\d+)\)/);
  const failed = r.stdout.match(/(\d+) failed/);
  return { files: files ? Number(files[2]) : null, filesPassed: files ? Number(files[1]) : null, tests: tests ? Number(tests[2]) : null, testsPassed: tests ? Number(tests[1]) : null, failed: failed ? Number(failed[1]) : 0 };
};
const selfCheckCounts = r => { const j = JSON.parse(r.stdout); return { ...j.counts, failedChecks: j.checks.filter(c => !c.pass).map(c => c.name) }; };

record('runtime: node', ['node', '--version']);
record('runtime: npm', ['npm', '--version']);
record('focused vitest (five required files; equivalent of npx vitest run ... with the controller-mandated runner flags)',
  ['node', 'node_modules/vitest/vitest.mjs', 'run', '--configLoader', 'runner', '--no-cache',
    'src/logic/currentSchemaVerification.test.ts', 'src/data/skillEvidenceUpgrade.test.ts', 'src/data/skillEvidenceValidationParity.test.ts',
    'src/data/migrationSafety.test.ts', 'src/data/migrations.test.ts'], vitestCounts);
record('helper node tests', ['node', '--test', 'scripts/mac-schema14-profile-snapshot.test.mjs'], r => {
  const n = k => Number((r.stdout.match(new RegExp(`^# ${k} (\\d+)`, 'm')) ?? [])[1]);
  return { tests: n('tests'), pass: n('pass'), fail: n('fail'), skipped: n('skipped') };
});
const proofRun = record('disposable proof runner', ['node', 'scripts/mac-schema14-verification-proof.mjs'], r => {
  const m = r.stdout.match(/^(PASS|FAIL): (\d+)\/(\d+) stages; receipt (.+)$/m);
  return { verdict: m?.[1], stagesPassed: Number(m?.[2]), stages: Number(m?.[3]), receiptPath: m?.[4] };
});
record('schema-14 helper self-check (source-only, run by the proof runner in a disposable copy)', ['node', 'scripts/mac-schema14-verification-proof.mjs', 'self-check'], selfCheckCounts);
record('distributed schema-14 helper refuses self-check (no test route; expected exit 2)', ['node', 'scripts/mac-schema14-profile-snapshot.mjs', 'self-check']);
record('historical schema-13 helper self-check (source-only; one expected ceiling alarm)', ['node', 'scripts/mac-schema13-profile-snapshot.mjs', 'self-check'], selfCheckCounts);
record('typecheck', ['npm', 'run', 'typecheck']);
record('cargo lock sync', ['npm', 'run', 'test:cargo-lock']);
record('whitespace: tracked changes', ['git', 'diff', '--check']);
const untracked = text(['git', 'ls-files', '--others', '--exclude-standard']).split('\n').filter(p => p && !p.startsWith('node_modules'));
const newFileCheck = untracked.map(p => {
  const r = spawnSync('git', ['diff', '--no-index', '--check', '/dev/null', p], { cwd: WT, env, encoding: 'utf8' });
  return { path: p, whitespaceErrors: r.stdout.trim() };
});
commands.push({ label: 'whitespace: new untracked files (git diff --no-index --check /dev/null <file>; exit 1 only means "differs from empty")', argv: ['git', 'diff', '--no-index', '--check', '/dev/null', '<each new file>'], cwd: WT, exit: newFileCheck.every(f => f.whitespaceErrors === '') ? 0 : 1, counts: { files: newFileCheck.length, withErrors: newFileCheck.filter(f => f.whitespaceErrors).length }, results: newFileCheck });
// The same check without git or /dev/null: trailing whitespace, and a final newline, in every changed or new file.
const scanned = [...ALLOWED, ...untracked.filter(p => !ALLOWED.includes(p))].filter(p => fs.existsSync(path.join(WT, p)) && fs.statSync(path.join(WT, p)).isFile());
const scan = scanned.map(p => {
  const body = fs.readFileSync(path.join(WT, p), 'utf8');
  const lines = body.split('\n').map((l, i) => [i + 1, l]).filter(([, l]) => /[ \t]+$/.test(l)).map(([n]) => n);
  return { path: p, trailingWhitespaceLines: lines, endsWithNewline: body.endsWith('\n') };
});
commands.push({ label: 'whitespace: git-free scan of every changed or new file', argv: ['(in-process scan)'], cwd: WT, exit: scan.every(f => f.trailingWhitespaceLines.length === 0 && f.endsWithNewline) ? 0 : 1, counts: { files: scan.length, withErrors: scan.filter(f => f.trailingWhitespaceLines.length || !f.endsWithNewline).length }, results: scan });

const proofPath = commands.find(c => c.label === 'disposable proof runner').counts?.receiptPath;
const proof = proofPath ? JSON.parse(fs.readFileSync(proofPath, 'utf8')) : null;

const byLabel = l => commands.find(c => c.label.startsWith(l));
const cargo = byLabel('cargo lock sync');
const summary = {
  focusedVitest: byLabel('focused vitest').counts,
  helperNodeTests: byLabel('helper node tests').counts,
  proofRunner: { exit: proofRun.exit, ...byLabel('disposable proof runner').counts },
  schema14SelfCheck: byLabel('schema-14 helper').counts,
  distributedSelfCheckRefusal: { exit: byLabel('distributed schema-14 helper refuses').exit, stderr: byLabel('distributed schema-14 helper refuses').stderr.trim().split('\n')[0], expected: 'exit 2: the distributed helper has no test route' },
  schema13SelfCheck: { ...byLabel('historical schema-13').counts, expected: 'exit 1 with exactly one failure: the intentional live-source ceiling alarm' },
  typecheck: { exit: byLabel('typecheck').exit },
  cargoLock: {
    exit: cargo.exit,
    status: cargo.exit === 0 ? 'PASS' : 'FAIL',
    note: 'measured in this run; the owner installed Rust/Cargo before round 3. The round-1/round-2 BLOCKED result is kept under reviewHistory.',
  },
  whitespace: { tracked: byLabel('whitespace: tracked').exit, newFiles: byLabel('whitespace: new').exit, gitFreeScan: byLabel('whitespace: git-free').exit },
  build: 'not run: no app-shared runtime code changed (scripts, one test file and docs only); typecheck covers the test file',
};
// The previous review round, recorded as data. Its controller results are not superseded by
// this run; each finding is listed with what changed and which check of this run covers it.
const round1Review = {
  approved: false,
  controllerResults: [
    { command: 'node node_modules/vitest/vitest.mjs run src/logic/currentSchemaVerification.test.ts --configLoader runner --no-cache', exit: 1, counts: '7 passed, 1 failed', failure: 'src/logic/currentSchemaVerification.test.ts:325, schema-14 restore/tamper case: a synthetic managed document had two hard links' },
    { command: '/opt/homebrew/opt/node@22/bin/node --test scripts/mac-schema14-profile-snapshot.test.mjs', exit: 0, counts: '11 passed' },
    { command: '/opt/homebrew/opt/node@22/bin/node scripts/mac-schema14-verification-proof.mjs', exit: 1, counts: '8/10 stages', failure: 'source-identity and protected-sources-unchanged blocked: the sandbox denied /dev/null, which every git process opens at startup' },
    { command: 'npm run test:cargo-lock', exit: 1, failure: 'Cargo toolchain missing' },
  ],
  findings: [
    { finding: 'distributed testContext route in scripts/mac-schema14-profile-snapshot.mjs', change: 'removed. snapshot() always takes operatorLane(), which returns only the approved lane; the scratch lane, adapter and self-check entry exist only in disposable copies written by scripts/mac-schema14-verification-proof.mjs (writeDisposableHelper). The distributed CLI refuses self-check.', coveredBy: ['proof stage distributed-helper-lane', 'node --test: distributed helper (2 tests)', 'distributed schema-14 helper refuses self-check'] },
    { finding: 'hard-linked synthetic managed document in the vitest restore/tamper case', change: 'The failure did not reproduce in the implementer environment, so its exact cause is unconfirmed. Fixtures no longer depend on a platform copy primitive: cloneScratchProfile no longer uses fs.cpSync; it rewrites every file byte for byte into a new inode and refuses a clone that is not single-linked. The vitest file asserts each document is single-linked before every capture in that case. The hard-link refusal itself is unchanged.', coveredBy: ['focused vitest', 'node --test: clones are independent single-linked files', 'schema-14 self-check: guard: a hard-linked managed document is refused'] },
    { finding: 'proof source-identity and protected-sources-unchanged depended on git (/dev/null)', change: 'both stages now read .git (HEAD, refs, index) and worktree bytes directly; no git process is started by the proof runner. Tracked paths outside the allowed list are checked against a pinned digest of the pinned commit\'s tree.', coveredBy: ['proof stage source-identity', 'proof stage protected-sources-unchanged'], residual: 'not re-run inside the controller\'s sandbox; this run used the implementer sandbox' },
    { finding: 'npm run test:cargo-lock blocked by the missing Cargo toolchain', change: 'none possible here: global installation is not permitted', coveredBy: ['cargo lock sync'], residual: 'still BLOCKED; needs a person with Cargo, or CI' },
    { finding: 'no observed pre-edit receipt', change: 'kept as a stated limitation (identity.preEditBaseline.limitation); not reconstructed into a claim', coveredBy: [] },
  ],
};
const round2ReceiptPath = '/private/tmp/hfd-schema14-consolidate/round3/round2-verification-receipts.json';
const preFixPath = '/private/tmp/hfd-schema14-consolidate/round3/proof-before-walker-fix.node26.json';
