// Disposable (round 3): writes source-manifest.json, then SHA256SUMS (excluding itself), after the receipt exists.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
const EV = 'docs/evidence/mac-schema14-verification-preparation-2026-10-11';
const sha = p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const receipt = JSON.parse(fs.readFileSync(`${EV}/verification-receipts.json`, 'utf8'));
const deliverables = [
  'scripts/mac-schema13-profile-snapshot.mjs', 'scripts/mac-schema14-profile-snapshot.mjs', 'scripts/mac-schema14-profile-snapshot.test.mjs',
  'scripts/mac-schema14-verification-proof.mjs', 'src/logic/currentSchemaVerification.test.ts',
  'docs/MAC_SCHEMA14_VERIFICATION_PREPARATION_REPORT_2026-10-11.md', 'docs/PROJECT_HANDOFF.md',
  `${EV}/README.md`, `${EV}/RUNBOOK.md`, `${EV}/verification-receipts.json`,
];
const files = deliverables.map(p => ({ path: p, bytes: fs.statSync(p).size, sha256: sha(p) }));
const measured = Object.fromEntries(receipt.identity.preEditBaseline.allowedPathHashes.map(h => [h.path, h.current]));
const drift = Object.entries(measured).filter(([p, h]) => files.find(f => f.path === p)?.sha256 !== h).map(([p]) => p);
if (drift.length) { console.error(`REFUSED: files changed after the receipt was generated: ${drift.join(', ')}`); process.exit(2); }
const manifest = {
  schema: 'hfd-schema14-source-manifest/1',
  pinnedCommit: receipt.identity.pinnedCommit,
  head: receipt.identity.head,
  generatedAfter: { receipt: `${EV}/verification-receipts.json`, receiptGeneratedAt: receipt.generatedAt },
  measuredByReceipt: { note: 'every allowed source path hashed by the receipt run equals the file listed here (checked when this manifest was generated)', paths: Object.keys(measured).length },
  baseHashesAtPinnedHead: receipt.identity.preEditBaseline.allowedPathHashes.map(({ path: p, atPinnedHead }) => ({ path: p, atPinnedHead })),
  files,
  excluded: { [`${EV}/source-manifest.json`]: 'this file (listed in SHA256SUMS)', [`${EV}/SHA256SUMS`]: 'never hashes itself' },
  previousInventories: { note: 'the round-2 manifest and SHA256SUMS went stale when files changed after they were generated (round-2 review: 9/10 and 3/4 mismatches); archived unchanged outside the repository', manifestSha256: sha('/private/tmp/hfd-schema14-consolidate/round3/round2-source-manifest.json'), sha256sumsSha256: sha('/private/tmp/hfd-schema14-consolidate/round3/round2-SHA256SUMS') },
  generator: { path: '/private/tmp/hfd-schema14-consolidate/round3/manifest-round3.mjs', sha256: sha(new URL(import.meta.url).pathname), source: fs.readFileSync(new URL(import.meta.url).pathname, 'utf8') },
};
fs.writeFileSync(`${EV}/source-manifest.json`, `${JSON.stringify(manifest, null, 2)}\n`);
const sums = ['README.md', 'RUNBOOK.md', 'source-manifest.json', 'verification-receipts.json'].map(f => `${sha(path.join(EV, f))}  ${f}`).join('\n');
fs.writeFileSync(`${EV}/SHA256SUMS`, `${sums}\n`);
console.log(sums);

